/*
 * A246046  [Pi((n + Pi/2)/(Pi -1) - 1/2)]; complement of A062389.
 * https://oeis.org/A246046
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 1, u16 n <= 2, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Search-based computation:  a(n) is the nth positive integer k ≥ 2 that is
 * not equal to floor((2m+1)*π/2) for any integer m ≥ 0.
 * The missing numbers belong to the Beatty sequence generated by π/2 + mπ.
 * Since we cannot use floating‑point arithmetic, we use a high‑precision
 * rational approximation of π:
 *    π ≈ 104348/33215  (error < 10⁻¹⁰)
 * The missing value for index m is
 *    floor((2m+1) * π / 2) ≈ ((2m+1) * 104348) / 66430
 * The algorithm scans the integers starting at 2, skipping these values,
 * until the requested rank n is reached.  This runs in O(n) time and
 * uses only integer operations.  */

#include <assert.h>

seq_t a(idx_t n)
{
    assert(n >= 1);

    idx_t count = 0;        /* how many valid numbers we have found */
    idx_t k = 2;            /* current candidate integer (starts at 2) */
    idx_t m = 0;            /* index into the missing Beatty sequence */

    /* Current missing number = floor((2m+1)*π/2) ≈ ((2m+1)*104348)/66430 */
    static const seq_t NUM_PI = 104348;   /* numerator of π approximation  */
    static const seq_t DEN_PI_HALF = 66430; /* 2 * denominator of π approximation */

    seq_t missing = ((seq_t)(2*m + 1) * NUM_PI) / DEN_PI_HALF;

    while (1) {
        /* Advance the missing value until it is ≥ the current candidate k */
        while ((seq_t)k > missing) {
            ++m;
            missing = ((seq_t)(2*m + 1) * NUM_PI) / DEN_PI_HALF;
        }

        /* If k is not a missing number, it belongs to the sequence */
        if ((seq_t)k != missing) {
            ++count;
            if (count == n)
                return (seq_t)k;   /* found the nth term */
        } else {
            /* Skip the missing number and advance to the next one */
            ++m;
            missing = ((seq_t)(2*m + 1) * NUM_PI) / DEN_PI_HALF;
        }
        ++k;   /* move to the next integer candidate */
    }
}
